/* AeroCare preparation rules: supported examples, never clinical clearance. */
(function(root){
const sources={airindia:{name:'Air India · Medical needs and clearance',url:'https://www.airindia.com/in/en/travel-information/health-medical-assistance/medical-needs-clearance.html'},emirates:{name:'Emirates · MEDIF guidance',url:'https://www.emirates.com/us/english/before-you-fly/health/medical-information-forms/'},kidney:{name:'National Kidney Foundation · Travel preparation',url:'https://www.kidney.org/kidney-topics/travel-tips-guide-kidney-patients'}};
const checked='5 November 2026';
function assess(p){
 const supports=Array.isArray(p.supports)?p.supports:[],condition=!!(p.condition&&p.condition!=='none');
 const supported=['Air India','Emirates'].includes(p.airline),source=p.airline==='Emirates'?sources.emirates:sources.airindia;
 const individual=!supported||p.condition==='other'||p.stability!=='stable'||p.recent==='yes'||(p.airline==='Emirates'&&condition);
 const medical=!!(p.recent==='yes'||p.stability!=='stable'||supports.some(x=>['oxygen','equipment','stretcher'].includes(x))||(condition&&p.airline==='Air India')||(condition&&p.condition==='kidney'));
 const tasks=[],docs=[];
 function task(id,title,detail,why,owner,kind='task',ref=source){tasks.push({id,title,detail,why,owner,kind,source:ref});}
 task('medicines','Pack medicines and relevant records in your cabin bag','Prepare prescribed medicines and the relevant travel records. Keep the medication schedule agreed with your clinician.','You need access to your prescribed medicines during the journey.','Passenger');
 if(medical){
 task('review','Prepare your medical-review documents','Arrange the physician-completed form and current report listed in Documents. Your treating clinician completes the medical sections; the airline reviews the case.','Your selected condition, recent event or support needs trigger our example medical-review workflow.','Passenger + treating clinician','document');
 docs.push({id:'medif',title:'Physician-completed MEDIF',detail:'Prepare the airline form with the journey details and the treating clinician’s medical sections, certification and contact details.',source,why:'This form gives the medical reviewer structured information relevant to your journey.'});
 docs.push({id:'report',title:'Current medical report',detail:p.airline==='Air India'?'Prepare a clinician-issued report dated within 10 days of departure, describing your condition and fitness to fly.':'Prepare a current report with the relevant diagnosis, treatment and travel support needs for medical review.',source,why:'The review must use current information. Date checks do not validate medical content.'});
 if(p.airline==='Emirates')task('deadline','Have the complete MEDIF ready at least 48 hours before departure','AeroCare includes this timing in your preparation plan. For the real process, the complete form must reach Emirates at least 48 hours before travel.','Emirates publishes a minimum 48-hour submission lead time.','Passenger + clinician','task');
 }
 if(p.recent==='yes')task('procedure','Obtain a recovery and travel assessment','Have your treating clinician assess the recent procedure or hospital stay. An individual review must establish any waiting period; this prototype cannot calculate it.','The procedure type, recovery and exact dates are needed to assess timing.','Treating clinician','review');
 if(p.condition==='kidney')task('kidney','Arrange your kidney-care travel plan','Discuss the journey with your treating team. If dialysis is needed away from home, organise treatment dates, a receiving centre and transfer of relevant records.','Kidney treatment may need coordination at the destination. This is care planning, not a prescription.','Passenger + kidney-care team','task',sources.kidney);
 if(supports.includes('oxygen')||supports.includes('equipment')){
 task('equipment','Prepare the oxygen / equipment request','Provide the device make and model, battery details and clinician’s statement of the medical need. Any oxygen prescription must come from your clinician.','The selected support requires medical and operational details before arrangements can be confirmed.','Passenger + treating clinician','document');
 docs.push({id:'equipment',title:'Oxygen / equipment details',detail:'Prepare the device information, battery arrangements and relevant clinician statement. This demo cannot check device approval or prescribe oxygen.',source,why:'Equipment acceptance and the available service need a separate review.'});
 }
 if(supports.includes('wheelchair'))task('wheelchair','Specify your mobility assistance needs','Describe whether you can walk in the cabin or climb steps, and whether you are bringing a mobility aid. Sharing creates a demo request; confirmation appears separately.','You selected airport mobility assistance.','Passenger','assistance');
 if(supports.includes('stretcher')){task('escort','Prepare stretcher and escort arrangements','Record the required escort and stretcher support. Service availability remains pending until separately confirmed.','You selected stretcher or medical escort support.','Passenger + care team','assistance');docs.push({id:'escort',title:'Escort information',detail:'Prepare escort details and the undertaking required for the applicable stretcher case.',source,why:'The airline needs the care arrangements for this special service.'});}
 if(individual)task('individual','Individual review needed for the remaining requirements','AeroCare cannot establish a complete plan from these answers. The medical reviewer needs to resolve the outstanding requirements before the plan can be treated as complete.','Your circumstances fall outside the supported example rules. We will not invent requirements or mark the case cleared.','Medical reviewer','review');
 return {medical,changed:p.stability!=='stable',individual,tasks,docs,source,checked};
}
function checkDocuments(p,records){const a=assess(p);return a.docs.map(d=>{const rec=records[d.id];let status='Missing',detail='No fictional file record yet.',ok=false;if(rec){status='Record present · content unchecked';detail='Only the filename and any entered date are checked. Authenticity, signatures and clinical content are not verified.';ok=true;if(d.id==='report'&&p.airline==='Air India'){const issued=rec.issuedDate?new Date(rec.issuedDate+'T12:00:00Z'):null,flight=new Date(p.departure+'T12:00:00Z');const age=issued?(flight-issued)/86400000:NaN;if(!Number.isFinite(age)){status='Issue date needed';detail='Enter the fictional report’s issue date for the preparation-date check.';ok=false;}else if(age<0){status='Date needs correction';detail='The report issue date cannot be after departure.';ok=false;}else if(age>10){status='Report date outside the 10-day window';detail='Prepare a report dated within 10 days of departure.';ok=false;}else{status='Record + date check passed';detail='The entered date meets this example rule. Medical content, authenticity and acceptance remain unchecked.';}}}return {...d,status,checkDetail:detail,ok};});}
const api={assess,checkDocuments,sources,checked};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.AeroRules=api;
})(typeof window!=='undefined'?window:globalThis);
